/**
 * Default (scope=mine) returns only sprints aligned to the caller — as consultant, host, or co-host. Pass scope=all to get the team-wide register used by the Sprint Tracking page.

 * @summary List T-Sprint sessions (scoped to caller by default)
 */
export const getListSprintsUrl = (params?: ListSprintsParams) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/sprints?${stringifiedParams}`
    : `/api/sprints`;
};

export const listSprints = async (
  params?: ListSprintsParams,
  options?: RequestInit,
): Promise<Sprint[]> => {
  return customFetch<Sprint[]>(getListSprintsUrl(params), {
    ...options,
    method: "GET",
  });
};

