/**
 * @summary (Admin only) Upload an xlsx file (ISB summary / JU summary / Sheet Tracking)
 */
export const getImportSheetUrl = () => {
  return `/api/admin/import`;
};

export const importSheet = async (
  importSheetBody: ImportSheetBody,
  options?: RequestInit,
): Promise<ImportSheet200> => {
  const formData = new FormData();
  if (importSheetBody.file !== undefined) {
    formData.append(`file`, importSheetBody.file);
  }
  if (importSheetBody.kind !== undefined) {
    formData.append(`kind`, importSheetBody.kind);
  }

  return customFetch<ImportSheet200>(getImportSheetUrl(), {
    ...options,
    method: "POST",
    body: formData,
  });
};

